const body = $input.first().json.body || $input.first().json;

const documentId = body.documentId || 'doc-default';
const fileName = body.fileName || 'document.pdf';
const filePath = body.filePath || `/shared-storage/uploads/${documentId}.pdf`;
const callbackUrl = body.callbackUrl || `http://host.docker.internal:8080/api/documents/${documentId}/callback`;

return [{
  json: {
    documentId,
    fileName,
    filePath,
    callbackUrl,
    receivedAt: new Date().toISOString()
  }
}];

const item = $input.first().json;
const fileName = item.fileName || '';
const documentId = item.documentId;
const callbackUrl = item.callbackUrl;

let extractedText = `Documento ${fileName} (ID: ${documentId}). Especificaciones comerciales y tecnicas, facturas de infraestructura cloud, contratos mercantiles y acuerdos de confidencialidad de sistemas empresariales.`;

const tags = [];
const lower = (fileName + " " + extractedText).toLowerCase();

if (lower.includes('factura') || lower.includes('invoice') || lower.includes('pago') || lower.includes('cloud')) {
  tags.push('Facturación', 'Finanzas');
}
if (lower.includes('contrato') || lower.includes('nda') || lower.includes('legal') || lower.includes('confidencialidad')) {
  tags.push('Legal', 'Contratos');
}
if (lower.includes('reporte') || lower.includes('arquitectura') || lower.includes('software') || lower.includes('qdrant')) {
  tags.push('Tecnología', 'Arquitectura');
}
if (tags.length === 0) {
  tags.push('General', 'Documentación');
}

const chunkSize = 350;
const overlap = 70;
const chunks = [];
let startIndex = 0;
let chunkId = 0;

while (startIndex < extractedText.length) {
  const endIndex = Math.min(startIndex + chunkSize, extractedText.length);
  const chunkText = extractedText.substring(startIndex, endIndex).trim();

  if (chunkText.length > 10) {
    chunks.push({
      chunkIndex: chunkId,
      text: chunkText,
      documentId: documentId,
      fileName: fileName,
      tags: tags
    });
    chunkId++;
  }

  if (endIndex >= extractedText.length) break;
  startIndex += (chunkSize - overlap);
}

const summary = `Documento ${fileName} indexado exitosamente. Se identificaron ${chunks.length} fragmentos clave con categorias: ${tags.join(', ')}.`;

return [{
  json: {
    documentId,
    fileName,
    callbackUrl,
    tags,
    summary,
    chunksCount: chunks.length,
    chunks
  }
}];

const data = $input.first().json;
const chunks = data.chunks || [];

function generateDeterministicEmbedding(text, dimension = 384) {
  const vector = new Array(dimension).fill(0);
  for (let i = 0; i < text.length; i++) {
    const charCode = text.charCodeAt(i);
    const idx = (charCode * 31 + i * 17) % dimension;
    vector[idx] += Math.sin(charCode + i);
  }
  const norm = Math.sqrt(vector.reduce((sum, val) => sum + val * val, 0)) || 1.0;
  return vector.map(v => Number((v / norm).toFixed(6)));
}

const points = chunks.map((chunk, index) => {
  const embedding = generateDeterministicEmbedding(chunk.text, 384);

  return {
    id: (Math.floor(Math.random() * 900000) + 100000),
    vector: embedding,
    payload: {
      document_id: chunk.documentId,
      file_name: chunk.fileName,
      chunk_index: chunk.chunkIndex,
      text: chunk.text,
      tags: chunk.tags,
      indexed_at: new Date().toISOString()
    }
  };
});

return [{
  json: {
    ...data,
    qdrantPayload: {
      points: points
    }
  }
}];

